"""Application logic for the photo-sharing website (Stages 2 and 3).

This module contains no AWS credentials and never creates AWS clients;
the caller supplies an S3 client object and a DB-API 2.0 connection.
"""

import os
import re
import uuid
from datetime import datetime, timezone

_ALLOWED_CONTENT_TYPES = {"image/jpeg", "image/png"}
_MAX_BYTES = 5 * 1024 * 1024
_SAFE_CHARS_RE = re.compile(r"[^A-Za-z0-9._-]")


def init_db(conn) -> None:
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            s3_key TEXT NOT NULL,
            uploaded_at TEXT NOT NULL
        )
        """
    )
    conn.commit()


def _utc_now_iso() -> str:
    # Fixed-precision ISO 8601 UTC timestamp, e.g. "2024-01-01T12:34:56Z"
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def save_photo_metadata(conn, title, description, s3_key) -> int:
    uploaded_at = _utc_now_iso()
    cur = conn.cursor()
    cur.execute(
        "INSERT INTO photos (title, description, s3_key, uploaded_at) VALUES (?, ?, ?, ?)",
        (title, description, s3_key, uploaded_at),
    )
    conn.commit()
    new_id = cur.lastrowid
    if new_id is None:
        cur.execute("SELECT last_insert_rowid()")
        new_id = cur.fetchone()[0]
    return new_id


def search_photos(conn, term):
    cur = conn.cursor()
    cur.execute(
        "SELECT id, title, description, s3_key, uploaded_at FROM photos ORDER BY id ASC"
    )
    rows = cur.fetchall()

    needle = str(term).casefold()

    results = []
    for row in rows:
        row_id, title, description, s3_key, uploaded_at = row[0], row[1], row[2], row[3], row[4]
        title_match = needle in (title.casefold() if title is not None else "")
        desc_match = needle in (description.casefold() if description is not None else "")
        if title_match or desc_match:
            results.append(
                {
                    "id": row_id,
                    "title": title,
                    "description": description,
                    "s3_key": s3_key,
                    "uploaded_at": uploaded_at,
                }
            )
    return results


def _safe_name(filename: str) -> str:
    base = os.path.basename(filename)
    if base in ("", ".", ".."):
        base = "file"
    return _SAFE_CHARS_RE.sub("_", base)


def upload_photo(s3, bucket, filename, data, content_type) -> str:
    if content_type not in _ALLOWED_CONTENT_TYPES:
        raise ValueError(f"Unsupported content type: {content_type!r}")

    if len(data) > _MAX_BYTES:
        raise ValueError(
            f"File too large: {len(data)} bytes exceeds limit of {_MAX_BYTES} bytes"
        )

    safe_name = _safe_name(filename)
    key = f"photos/{uuid.uuid4().hex}/{safe_name}"

    s3.put_object(Bucket=bucket, Key=key, Body=data, ContentType=content_type)

    return key


def photo_url(s3, bucket, key, expires=3600) -> str:
    if not isinstance(expires, int) or isinstance(expires, bool) or not (1 <= expires <= 3600):
        raise ValueError("expires must be an integer between 1 and 3600 seconds inclusive")

    return s3.generate_presigned_url(
        "get_object",
        Params={"Bucket": bucket, "Key": key},
        ExpiresIn=expires,
    )


def handle_upload(conn, s3, bucket, title, description, filename, data, content_type) -> int:
    key = upload_photo(s3, bucket, filename, data, content_type)

    try:
        new_id = save_photo_metadata(conn, title, description, key)
    except Exception:
        s3.delete_object(Bucket=bucket, Key=key)
        raise

    return new_id
